import{at as e,it as t,n,vt as r}from"./chunks/framework.CawbQXU3.js";var i=JSON.parse(`{"title":"Hooks","description":"Details about writing and setting up hooks","frontmatter":{"title":"Hooks","description":"Details about writing and setting up hooks","icon":null,"date":"2024-08-15T00:00:00.000Z"},"headers":[],"relativePath":"reference/hooks/index.md","filePath":"reference/hooks.md","lastUpdated":1793537972000}`),a={name:`reference/hooks/index.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h2 id="hooks" tabindex="-1">Hooks <a class="header-anchor" href="#hooks" aria-label="Permalink to “Hooks”">​</a></h2><h3 id="hook-suites" tabindex="-1">Hook Suites <a class="header-anchor" href="#hook-suites" aria-label="Permalink to “Hook Suites”">​</a></h3><p>A <em>hook suite</em> is a list of <em>hooks</em> to run sequentially. A <em>hook</em> is either an individual shell command or an executable script.</p><p>There are three hook suites: <em>setup, pre-commit,</em> and <em>post-commit.</em> During the version increment process this is the order of operations:</p><ol><li>Run <em>setup</em> hooks</li><li>Increment version</li><li>Change files</li><li>Run <em>pre-commit</em> hooks</li><li>Commit and tag</li><li>Run <em>post-commit</em> hooks</li></ol><div class="info custom-block"><p class="custom-block-title">Note</p><p>Don&#39;t confuse the <em>pre-commit</em> and <em>post-commit</em> hook suites with Git pre- and post-commit hooks. Those hook suites are named for their adjacency to the commit and tag operation.</p></div><h3 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to “Configuration”">​</a></h3><p>Configure each hook suite with the <code>setup_hooks</code>, <code>pre_commit_hooks</code>, or <code>post_commit_hooks</code> keys.</p><p>Each suite takes a list of strings. The strings may be individual commands:</p><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[tool.bumpversion]</span></span>
<span class="line"><span>setup_hooks = [</span></span>
<span class="line"><span>    &quot;git config --global user.email \\&quot;bump-my-version@github.actions\\&quot;&quot;,</span></span>
<span class="line"><span>    &quot;git config --global user.name \\&quot;Testing Git\\&quot;&quot;,</span></span>
<span class="line"><span>    &quot;git --version&quot;,</span></span>
<span class="line"><span>    &quot;git config --list&quot;,</span></span>
<span class="line"><span>]</span></span>
<span class="line"><span>pre_commit_hooks = [&quot;cat CHANGELOG.md&quot;]</span></span>
<span class="line"><span>post_commit_hooks = [&quot;echo Done&quot;]</span></span></code></pre></div><p>or the path to an executable script:</p><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[tool.bumpversion]</span></span>
<span class="line"><span>setup_hooks = [&quot;path/to/setup.sh&quot;]</span></span>
<span class="line"><span>pre_commit_hooks = [&quot;path/to/pre-commit.sh&quot;]</span></span>
<span class="line"><span>post_commit_hooks = [&quot;path/to/post-commit.sh&quot;]</span></span></code></pre></div><div class="info custom-block"><p class="custom-block-title">Note</p><p>You can make a script executable using the following steps:</p><ol><li>Add a <a href="https://en.wikipedia.org/wiki/Shebang_(Unix)" target="_blank" rel="noreferrer">shebang</a> line to the top like <code>#!/bin/bash</code></li><li>Run <code>chmod u+x path/to/script.sh</code> to set the executable bit</li></ol></div><h3 id="safe-execution-and-shell-syntax" tabindex="-1">Safe execution and shell syntax <a class="header-anchor" href="#safe-execution-and-shell-syntax" aria-label="Permalink to “Safe execution and shell syntax”">​</a></h3><p>By default, bump-my-version executes hooks using <strong>argv-based execution</strong> (<code>shell=False</code>). Each hook string is parsed into an argument list using standard POSIX quoting rules, and the program is launched directly — no shell is involved.</p><p>This means hooks that rely on shell features will raise an error unless you explicitly opt in:</p><table tabindex="0"><thead><tr><th>Feature</th><th>Example</th><th>Requires opt-in?</th></tr></thead><tbody><tr><td>Pipes</td><td><code>echo hello | cat</code></td><td>Yes</td></tr><tr><td>Logical operators</td><td><code>cmd1 &amp;&amp; cmd2</code></td><td>Yes</td></tr><tr><td>Command separators</td><td><code>cmd1; cmd2</code></td><td>Yes</td></tr><tr><td>Redirects</td><td><code>echo hi &gt; file.txt</code></td><td>Yes</td></tr><tr><td>Variable expansion</td><td><code>echo $MY_VAR</code></td><td>Yes</td></tr><tr><td>Command substitution</td><td><code>echo $(date)</code></td><td>Yes</td></tr><tr><td>Plain commands with arguments</td><td><code>git tag -a v1.0</code></td><td>No</td></tr><tr><td>Executable scripts</td><td><code>path/to/script.sh</code></td><td>No</td></tr></tbody></table><h4 id="rewriting-shell-syntax-hooks" tabindex="-1">Rewriting shell-syntax hooks <a class="header-anchor" href="#rewriting-shell-syntax-hooks" aria-label="Permalink to “Rewriting shell-syntax hooks”">​</a></h4><p>Most shell-syntax hooks can be replaced with a script file or explicit arguments:</p><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[tool.bumpversion]</span></span>
<span class="line"><span># These will raise HookError by default</span></span>
<span class="line"><span>post_commit_hooks = [</span></span>
<span class="line"><span>    &quot;echo $BVHOOK_NEW_VERSION &gt; version.txt&quot;,</span></span>
<span class="line"><span>    &quot;git log --oneline | head -5&quot;,</span></span>
<span class="line"><span>]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[tool.bumpversion]</span></span>
<span class="line"><span># Pass the script file directly — no shell required</span></span>
<span class="line"><span>post_commit_hooks = [</span></span>
<span class="line"><span>    &quot;path/to/update-version-file.sh&quot;,</span></span>
<span class="line"><span>    &quot;path/to/show-log.sh&quot;,</span></span>
<span class="line"><span>]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>#!/bin/bash</span></span>
<span class="line"><span>echo &quot;$BVHOOK_NEW_VERSION&quot; &gt; version.txt</span></span></code></pre></div><h4 id="allow-shell-hooks-compatibility-opt-in" tabindex="-1">allow_shell_hooks (compatibility opt-in) <a class="header-anchor" href="#allow-shell-hooks-compatibility-opt-in" aria-label="Permalink to “allow_shell_hooks (compatibility opt-in)”">​</a></h4><p>If you cannot immediately rewrite your hooks, set <code>allow_shell_hooks = true</code> to restore shell execution:</p><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[tool.bumpversion]</span></span>
<span class="line"><span>allow_shell_hooks = true</span></span>
<span class="line"><span>post_commit_hooks = [&quot;echo $BVHOOK_NEW_VERSION | tee version.txt&quot;]</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title custom-block-title-default">WARNING</p><p><code>allow_shell_hooks = true</code> restores the previous behavior but exposes you to shell-injection risks if any hook string is ever constructed from untrusted input. Prefer rewriting hooks to remove shell syntax and leaving this option at its default of <code>false</code>.</p></div><p><code>allow_shell_hooks</code></p><dl><dt>required</dt><dd>No</dd><dt>default</dt><dd><code>false</code></dd><dt>type</dt><dd>boolean</dd><dt>environment var</dt><dd><code>BUMPVERSION_ALLOW_SHELL_HOOKS</code></dd></dl><p>Whether to allow hook strings that contain shell metacharacters (pipes, redirects, variable expansion, etc.) to run via the system shell. When <code>false</code> (the default), any hook containing shell syntax raises a <code>HookError</code> with a migration message. When <code>true</code>, those hooks run with <code>shell=True</code> and a warning is logged.</p><h3 id="hook-environments" tabindex="-1">Hook Environments <a class="header-anchor" href="#hook-environments" aria-label="Permalink to “Hook Environments”">​</a></h3><p>Each hook has these environment variables set when executed.</p><h4 id="inherited-environment" tabindex="-1">Inherited environment <a class="header-anchor" href="#inherited-environment" aria-label="Permalink to “Inherited environment”">​</a></h4><p>All environment variables set before bump-my-version was run are available.</p><h4 id="date-and-time-fields" tabindex="-1">Date and time fields <a class="header-anchor" href="#date-and-time-fields" aria-label="Permalink to “Date and time fields”">​</a></h4><dl><dt><code>BVHOOK_NOW</code></dt><dd>The ISO-8601-formatted current local time without a time zone reference.</dd><dt><code>BVHOOK_UTCNOW</code></dt><dd>The ISO-8601-formatted current local time in the UTC time zone.</dd></dl><h4 id="source-code-management-fields" tabindex="-1">Source code management fields <a class="header-anchor" href="#source-code-management-fields" aria-label="Permalink to “Source code management fields”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Note</p><p>These fields will only have values if the code is in a Git or Mercurial repository.</p></div><dl><dt><code>BVHOOK_COMMIT_SHA</code></dt><dd>The latest commit reference.</dd><dt><code>BVHOOK_SHORT_COMMIT_SHA</code></dt><dd>The shortened version of the latest commit reference.</dd><dt><code>BHOOK_DISTANCE_TO_LATEST_TAG</code></dt><dd>The number of commits since the latest tag.</dd><dt><code>BVHOOK_IS_DIRTY</code></dt><dd>A boolean indicating if the current repository has pending changes.</dd><dt><code>BVHOOK_BRANCH_NAME</code></dt><dd>The current branch name.</dd><dt><code>BVHOOK_SHORT_BRANCH_NAME</code></dt><dd>The current branch name, converted to lowercase, with non-alphanumeric characters removed and truncated to 20 characters. For example, <code>feature/MY-long_branch-name</code> would become <code>featuremylongbranchn</code>.</dd></dl><h4 id="current-version-fields" tabindex="-1">Current version fields <a class="header-anchor" href="#current-version-fields" aria-label="Permalink to “Current version fields”">​</a></h4><dl><dt><code>BVHOOK_CURRENT_VERSION</code></dt><dd>The current version serialized as a string</dd><dt><code>BVHOOK_CURRENT_TAG</code></dt><dd>The current tag</dd><dt><code>BVHOOK_CURRENT_&lt;version component&gt;</code></dt><dd>Each version component defined by the <a href="/bump-my-version/pr-preview/pr-461/reference/configuration/global/#parse">version configuration parsing regular expression</a>. The default configuration would have <code>BVHOOK_CURRENT_MAJOR</code>, <code>BVHOOK_CURRENT_MINOR</code>, and <code>BVHOOK_CURRENT_PATCH</code> available.</dd></dl><h4 id="new-version-fields" tabindex="-1">New version fields <a class="header-anchor" href="#new-version-fields" aria-label="Permalink to “New version fields”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Note</p><p>These are not available in the <em>setup</em> hook suite.</p></div><dl><dt><code>BVHOOK_NEW_VERSION</code></dt><dd>The new version serialized as a string</dd><dt><code>BVHOOK_NEW_TAG</code></dt><dd>The new tag</dd><dt><code>BVHOOK_NEW_VERSION_TAG</code></dt><dd>An alias for <code>BVHOOK_NEW_TAG</code>, retained for backwards compatibility.</dd><dt><code>BVHOOK_NEW_&lt;version component&gt;</code></dt><dd>Each version component defined by the <a href="/bump-my-version/pr-preview/pr-461/reference/configuration/global/#parse">version configuration parsing regular expression</a>. The default configuration would have <code>BVHOOK_NEW_MAJOR</code>, <code>BVHOOK_NEW_MINOR</code>, and <code>BVHOOK_NEW_PATCH</code> available.</dd></dl><h3 id="version-placeholders-in-hook-commands" tabindex="-1">Version placeholders in hook commands <a class="header-anchor" href="#version-placeholders-in-hook-commands" aria-label="Permalink to “Version placeholders in hook commands”">​</a></h3><p>Hook command strings may contain version placeholders that bump-my-version replaces before executing the hook. This works with safe argv-based execution, so you do not need to enable <code>allow_shell_hooks</code> to use them.</p><div class="info custom-block"><p class="custom-block-title">Note</p><p>Placeholders are only substituted when <code>allow_shell_hooks</code> is <code>false</code> (the default). When <code>allow_shell_hooks</code> is <code>true</code>, hook commands are passed through unchanged so that shell variable expansion (<code>$BVHOOK_NEW_VERSION</code>) can be used instead.</p></div><p>The following placeholders are available:</p><table tabindex="0"><thead><tr><th>Placeholder</th><th>Value</th><th>Available in</th></tr></thead><tbody><tr><td><code>{current_version}</code></td><td>The current version serialized as a string</td><td>All hook suites</td></tr><tr><td><code>{current_&lt;component&gt;}</code></td><td>The value of a parsed version component, e.g. <code>{current_major}</code></td><td>All hook suites</td></tr><tr><td><code>{new_version}</code></td><td>The new version serialized as a string</td><td>Pre-commit and post-commit hooks</td></tr><tr><td><code>{new_&lt;component&gt;}</code></td><td>The value of a parsed new version component, e.g. <code>{new_major}</code></td><td>Pre-commit and post-commit hooks</td></tr></tbody></table><p>For example:</p><div class="language-toml" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tool</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bumpversion</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">current_version = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;1.2.3&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">pre_commit_hooks = [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;git tag release/{new_major}.{new_minor}&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span></code></pre></div><p>During a bump to <code>1.3.0</code>, the command becomes:</p><div class="language-console" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">console</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">git tag release/1.3</span></span></code></pre></div><p>Substituted values are shell-quoted, so a value containing spaces stays a single argument.</p><p>Placeholders that do not match a known version key are left unchanged, so existing commands with unrelated braces continue to work.</p><h3 id="outputs" tabindex="-1">Outputs <a class="header-anchor" href="#outputs" aria-label="Permalink to “Outputs”">​</a></h3><p>The <code>stdout</code> and <code>stderr</code> streams are echoed to the console if you pass the <code>-vv</code> option.</p><h3 id="dry-runs" tabindex="-1">Dry-runs <a class="header-anchor" href="#dry-runs" aria-label="Permalink to “Dry-runs”">​</a></h3><p>Bump my version does not execute any hooks during a dry run. With the verbose output option it will state which hooks it would have run.</p>`,56)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};